ottle\nde 120 req/min por IP. Tests: 9 casos nuevos en CatalogoPublicoApiTest.","tree":{"sha":"4b184196dfa29ec3ecb6fb3f13b579ed5ed58882","url":"https://api.github.com/repos/nbazaes/django-bazpos/git/trees/4b184196dfa29ec3ecb6fb3f13b579ed5ed58882"},"url":"https://api.github.com/repos/nbazaes/django-bazpos/git/commits/4fbdfaa0a330fbd27758d9d789765459a73118bd","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/167266564?v=4","events_url":"https://api.github.com/users/nbazaes/events{/privacy}","followers_url":"https://api.github.com/users/nbazaes/followers","following_url":"https://api.github.com/users/nbazaes/following{/other_user}","gists_url":"https://api.github.com/users/nbazaes/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/nbazaes","id":167266564,"login":"nbazaes","node_id":"U_kgDOCfhJBA","organizations_url":"https://api.github.com/users/nbazaes/orgs","received_events_url":"https://api.github.com/users/nbazaes/received_events","repos_url":"https://api.github.com/users/nbazaes/repos","site_admin":false,"starred_url":"https://api.github.com/users/nbazaes/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/nbazaes/subscriptions","type":"User","url":"https://api.github.com/users/nbazaes","user_view_type":"public"},"html_url":"https://github.com/nbazaes/django-bazpos/commit/4fbdfaa0a330fbd27758d9d789765459a73118bd","node_id":"C_kwDOQPMD6NoAKDRmYmRmYWEwYTMzMGZiZDI3NzU4ZDlkNzg5NzY1NDU5YTczMTE4YmQ","parents":[{"html_url":"https://github.com/nbazaes/django-bazpos/commit/db31d0a5d160efb954df4660c072827da80421cc","sha":"db31d0a5d160efb954df4660c072827da80421cc","url":"https://api.github.com/repos/nbazaes/django-bazpos/commits/db31d0a5d160efb954df4660c072827da80421cc"}],"sha":"4fbdfaa0a330fbd27758d9d789765459a73118bd","url":"https://api.github.com/repos/nbazaes/django-bazpos/commits/4fbdfaa0a330fbd27758d9d789765459a7